"""Generate src/svg_colors.inc: svgelements' color keywords (Color.parse_color_lookup), with
its first-match quirks (e.g. "aliceblue"), for import_svg.

    python scripts/gen_svg_colors.py src/svg_colors.inc
"""

import re
import sys

import svgelements

source = open(svgelements.svgelements.__file__, encoding="latin-1").read()
start = source.index("def parse_color_lookup")
end = source.index("def parse_color_hex")
names = []
for name in re.findall(r'if v == "([a-z]+)":', source[start:end]):
    if name not in names:
        names.append(name)
lines = [
    "// Generated by scripts/gen_svg_colors.py from svgelements %s. Don't edit." % svgelements.SVGELEMENTS_VERSION,
    "// clang-format off",
]
for name in names:
    lines.append('{"%s", 0x%08XULL},' % (name, svgelements.Color.parse_color_lookup(name)))
lines.append("// clang-format on")
open(sys.argv[1], "w", encoding="utf-8").write("\n".join(lines) + "\n")
print(len(names))
